// A call's convention (Fixpt's `r-conv-of`), by its callee's type: native
// (2), called with no look; `fx`, or a composable continuation, which may
// be of either (0, a call that looks); else cellular (1), as the stack
// compiler's `tcall`.
#[inline]
pub fn r_conv_at(a: i64) -> i64 {
    if cg_fx_call_p(a, get(cg_native_calls())) {
        2i64
    } else if cg_fx_call_p(a, get(cg_fx_calls())) {
        0i64
    } else {
        1i64
    }
}

#[inline]
pub fn r_invoke(g: kayak_rt::data::DataAt<'static, Rgen>, n: i64, tail: bool, conv: i64) -> () {
    if tail {
        r_leave(g);
        r_opnn(g, str_lit!("tailinvoke"), n, conv)
    } else {
        r_opnn(g, str_lit!("invoke"), n, conv)
    }
}

