// Names `r-identity-arg` tests against, made once (C264): a list written in place is
// made at each call.
#[inline]
pub fn r_identity_arg_names() -> Strings {
    static ONCE: std::sync::OnceLock<Strings> = std::sync::OnceLock::new();
    once(&ONCE, || {
        kayak_rt::heap_cons(str_lit!("+"), kayak_rt::heap_cons(str_lit!("-"), kayak_rt::heap_cons(str_lit!("*"), kayak_rt::nil())))
    })
}

// The operand an identity leaves (`x + 0`, `0 + x`, `x - 0`, `x * 1`,
// `1 * x`), in a list.
pub fn r_identity_arg(env: Renv, name: Str, args: Cxs) -> Cxs {
    if (not(i64_eq(size(args), 2i64)) || not(string_member_p(name, r_identity_arg_names()))) {
        nil::<kayak_rt::data::DataAt<'static, Cx>>()
    } else {
        let x = car(args);
        let y = car(cdr(args));
        let a = r_known(env, x);
        let b = r_known(env, y);
        let is = kayak_rt::closure2s((), |(), c: List<kayak_rt::data::DataAt<'static, Rconst>>, n: Int| {
            (not(null_p(c)) && {
                let tagcase_ = car(c);
                if Rconst::__is_RcInt(tagcase_) {
                    let (k,) = Rconst::__RcInt(tagcase_);
                    _eq(k, n)
                } else {
                    let z = tagcase_;
                    false
                }
            })
        });
        if (string_eq_p(name, str_lit!("+")) && is.call(b, int_lit(0))) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit!("+")) && is.call(a, int_lit(0))) {
            kayak_rt::heap_cons(y, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit!("-")) && is.call(b, int_lit(0))) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit!("*")) && is.call(b, int_lit(1))) {
            kayak_rt::heap_cons(x, kayak_rt::nil())
        } else if (string_eq_p(name, str_lit!("*")) && is.call(a, int_lit(1))) {
            kayak_rt::heap_cons(y, kayak_rt::nil())
        } else {
            nil::<kayak_rt::data::DataAt<'static, Cx>>()
        }
    }
}

