        if Rspecial::__is_Rspecial(tagcase_) {
            let (n, ps, body, at, k, ar, la,) = Rspecial::__Rspecial(tagcase_);
            r_nth_name(ps, k)
        } else { kayak_rt::data::no_variant() }
